/* Source: src/tokens.css */
/* Author: @jiuyi0204 | 森邮之间批准图色彩，结构切片。 */
:root {
 --sen-paper:#f5f0df; --sen-page:#e4dbc1; --sen-ink:#203e30;
 --sen-leaf:#526348; --sen-line:#53664c; --sen-soft:#e8e6d3;
 --sen-rust:#85552f; --sen-focus:#946a30; --sen-clear:transparent;
 --sen-font:"Noto Serif CJK SC","Source Han Serif SC","Songti SC",SimSun,serif;
 --sen-avatar:184px; --sen-ornament-width:850px;
 --st-theme-mobile-reading-width:42rem; --st-theme-mobile-reading-padding:1rem;
}


/* Source: src/kernel/scrollbars.css */
/*
 * v7 固定全局无滚动条外观内核。
 * 只隐藏浏览器滚动条外观，不修改 overflow、touch-action、pointer-events，
 * 不隐藏滚动容器、跳转键、功能按钮或 input[type="range"]。
 * 全局 * 是本项目唯一允许的无边界选择器例外，不得增加其他声明。
 */
::-webkit-scrollbar {
    display: none !important;
}

* {
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}


/* Source: src/chat-layout.css */
/* 1.14.0 index.html:7039 message_template; no generated people/text. */
body {background-color:var(--sen-page)}
#bg1 {background-color:var(--sen-page);background-image:none!important}
#chat {background:var(--sen-page);border:0;padding:10px 0;gap:12px;text-shadow:none;backdrop-filter:none;-webkit-backdrop-filter:none}
#chat .mes[is_system="false"] {
 display:flex;flex-direction:column;align-items:stretch;flex-shrink:0;
 box-sizing:border-box;inline-size:100%;padding:38px 0 30px;margin:0;
 border:1px solid var(--sen-line);border-radius:4px;background:var(--sen-paper);color:var(--sen-ink);
}
/* Reserved full ornament footprint; artwork follows slice approval. */
#chat .mes[is_system="false"] > .mesAvatarWrapper {
 align-self:center;inline-size:min(100%,var(--sen-ornament-width));max-inline-size:100%;min-inline-size:0;
 padding:10px 0 14px;margin-inline:auto;text-align:center;box-sizing:border-box;
}
#chat .mes[is_system="false"] > .mesAvatarWrapper > .avatar {
 inline-size:var(--sen-avatar);block-size:var(--sen-avatar);margin-inline:auto;
 border:5px solid var(--sen-paper);outline:1px solid var(--sen-line);border-radius:2px;box-sizing:border-box;flex:none;
}
#chat .mes[is_system="false"] > .mesAvatarWrapper > .avatar > img {
 width:100%;height:100%;max-height:none;border:0;border-radius:0;box-shadow:none;object-fit:cover;object-position:center;
}
#chat .mes[is_system="false"] > .mes_block {inline-size:100%;min-inline-size:0;padding:0;box-sizing:border-box}
#chat .mes[is_system="false"] > .mes_block > .ch_name {flex-direction:column;align-items:stretch;gap:5px;padding:0 12px 8px}
#chat .mes[is_system="false"] > .mes_block > .ch_name > .flex-container {justify-content:center;min-inline-size:0;flex:0 1 auto}
#chat .mes[is_system="false"] .ch_name .alignItemsBaseline {justify-content:center;align-items:center;flex-direction:column;gap:4px;min-inline-size:0;max-inline-size:100%}
#chat .mes[is_system="false"] .name_text {font-family:var(--sen-font);font-size:1.25em;color:var(--sen-ink);overflow-wrap:anywhere;text-align:center}
#chat .mes[is_system="false"] .timestamp {color:var(--sen-leaf);font-family:var(--sen-font);font-size:.85em;text-align:center}
#chat .mes[is_system="false"] > .mes_block > .mes_text {
 inline-size:min(100%,64rem);max-inline-size:100%;margin-inline:auto!important;padding:6px clamp(20px,4%,56px);box-sizing:border-box;
}
/* Native actions stay attached to message; expanded tools flow below metadata. */
#chat .mes[is_system="false"] .ch_name > .mes_buttons {position:absolute;inset-block-start:8px;inset-inline-end:10px;max-inline-size:calc(100% - 20px);flex-wrap:wrap}
body.expandMessageActions #chat .mes[is_system="false"] .ch_name > .mes_buttons,
#chat .mes[is_system="false"] .ch_name > .mes_buttons:has(.extraMesButtons.visible) {position:static;align-self:stretch;max-inline-size:100%}
#chat .mes[is_system="false"] .extraMesButtons {flex-wrap:wrap}
#chat .mes[is_system="false"] .mes_edit_buttons {float:none;flex-wrap:wrap;align-self:center;max-inline-size:100%;filter:none;gap:6px}
#chat .mes.selected {background-color:var(--sen-soft);outline:2px solid var(--sen-rust);outline-offset:-3px}
#chat .mes[is_system="true"] {color:var(--sen-ink);background:var(--sen-paper)}
@media (max-width:700px) {
 :root {--sen-avatar:142px;--sen-ornament-width:350px}
 #chat {padding:8px;gap:10px}
 #chat .mes[is_system="false"] {flex-direction:column;align-items:stretch;padding-block:38px 28px}
 #chat .mes[is_system="false"] > .mesAvatarWrapper {margin-inline:auto;align-self:center}
 #chat .mes[is_system="false"] > .mes_block {inline-size:100%;min-inline-size:0}
 #chat .mes[is_system="false"] > .mes_block > .mes_text {inline-size:min(100%,var(--st-theme-mobile-reading-width));margin-inline:auto!important;padding-inline:var(--st-theme-mobile-reading-padding)!important}
}



/* Source: src/full-text.css */
#chat .mes_text {color:var(--sen-ink);font-family:var(--sen-font);font-size:1em;font-weight:400;line-height:1.85;overflow-wrap:anywhere}
#chat .mes_text p {margin-block:0 .8em}
#chat .mes_text p:last-child {margin-bottom:0}
#chat .mes[is_user="true"] .mes_text {text-align:center}
#chat .mes_text :is(h1,h2,h3,h4,h5,h6) {color:var(--sen-ink);font-family:var(--sen-font);line-height:1.5}
#chat .mes_text :is(em,i,q,blockquote) {color:var(--sen-leaf)}
#chat .mes_text blockquote {border-inline-start:3px solid var(--sen-line);padding-inline:1em;margin-inline:0;background:var(--sen-soft)}
#chat .mes_text a {color:var(--sen-rust);text-decoration:underline}
#chat .mes_text :is(pre,code) {background:var(--sen-soft);color:var(--sen-ink);text-shadow:none;box-shadow:none}
#chat .mes_text pre {border:1px solid var(--sen-line);padding:12px;max-width:100%;overflow-x:auto}
#chat .mes_text pre code.hljs {background:var(--sen-soft);color:var(--sen-ink)}
#chat .mes_text code.hljs [class^="hljs-"] {color:var(--sen-ink);background:var(--sen-clear);text-shadow:none}
#chat .mes_text code.hljs :is(.hljs-string,.hljs-comment,.hljs-quote) {color:var(--sen-leaf)}
#chat .mes_text code.hljs :is(.hljs-keyword,.hljs-number,.hljs-title) {color:var(--sen-rust)}
#chat .mes_text ::selection {background:var(--sen-line);color:var(--sen-paper)}
#chat .mes_text table {display:block;overflow-x:auto;max-width:100%}
#chat .mes_text :is(th,td) {border:1px solid var(--sen-line);padding:.45em .7em}
#chat .mes_text img {max-width:100%;height:auto}


/* Source: src/windows/chat-controls.css */
/* Native icon drawing and visibility remain authoritative. */
#top-bar {background:var(--sen-paper);border:1px solid var(--sen-line);box-shadow:none;backdrop-filter:none;-webkit-backdrop-filter:none}
#top-settings-holder .drawer-icon {color:var(--sen-ink);opacity:1;filter:none;text-shadow:none;box-sizing:border-box;min-inline-size:28px;padding:4px;line-height:1.2;text-align:center}
#top-settings-holder .drawer-icon.openIcon {color:var(--sen-rust)}
#top-settings-holder .drawer-icon:hover {color:var(--sen-leaf)}
#send_form {background:var(--sen-paper);border:1px solid var(--sen-line);border-radius:4px;box-shadow:none;backdrop-filter:none;-webkit-backdrop-filter:none;padding:4px;box-sizing:border-box}
#nonQRFormItems {align-items:center;min-inline-size:0}
#send_textarea {min-inline-size:0;min-height:40px;height:auto;max-height:40dvh;color:var(--sen-ink);background-color:var(--sen-paper);border-inline:1px solid var(--sen-line);border-bottom:1px solid var(--sen-line);border-radius:4px;padding:7px 10px;font-family:var(--sen-font);font-size:var(--mainFontSize,1rem);line-height:1.5;text-shadow:none}
#send_textarea::placeholder {color:var(--sen-leaf);opacity:1}
#send_form #leftSendForm > div,#send_form #rightSendForm > div {color:var(--sen-ink);opacity:1;filter:none;text-shadow:none;box-shadow:none}
#send_form #leftSendForm > div:hover,#send_form #rightSendForm > div:hover {color:var(--sen-rust);filter:none}
#chat :is(.mes_button,.swipe_left,.swipe_right,.swipes-counter,.code-copy) {color:var(--sen-ink);opacity:1;filter:none;text-shadow:none}
#chat .mes_button {min-inline-size:26px;min-block-size:26px;line-height:24px;text-align:center;box-sizing:border-box}
#chat .mes_button:hover {color:var(--sen-rust)}
#chat :is(.edit_textarea,.reasoning_edit_textarea) {width:100%;box-sizing:border-box;background:var(--sen-paper);color:var(--sen-ink);border:1px solid var(--sen-line);padding:12px;border-radius:4px;font-family:var(--sen-font);line-height:1.8;filter:none;opacity:1;text-shadow:none;box-shadow:none}
#chat :is(.mes_edit_buttons,.mes_reasoning_actions) .menu_button {background:var(--sen-soft);color:var(--sen-ink);border:1px solid var(--sen-line);filter:none;opacity:1;text-shadow:none;box-shadow:none;min-width:30px;min-height:30px}
#chat :is(.mes_edit_buttons,.mes_reasoning_actions) :is(.mes_edit_done,.mes_reasoning_edit_done) {background:var(--sen-line);color:var(--sen-paper)}
#chat :is(.mes_edit_buttons,.mes_reasoning_actions) :is(.mes_edit_cancel,.mes_reasoning_edit_cancel) {border-color:var(--sen-rust);color:var(--sen-rust)}
#chat :is(.mes_edit_buttons,.mes_reasoning_actions) .menu_button:hover {background:var(--sen-paper);color:var(--sen-rust)}
#chat :is(.mes_edit_buttons,.mes_reasoning_actions) .menu_button:active {background:var(--sen-line);color:var(--sen-paper)}
#chat :is(.mes_edit_buttons,.mes_reasoning_actions) .menu_button:is(:disabled,[disabled],.disabled) {background:var(--sen-soft);color:var(--sen-leaf);border-style:dashed}
#chat .mes_reasoning_details {background:var(--sen-soft);color:var(--sen-ink);border:1px solid var(--sen-line);border-radius:4px;margin:8px 16px;padding:8px 12px}
#chat :is(.mes_reasoning_header,.mes_reasoning_header_block,.mes_reasoning_summary,.mes_reasoning) {background:var(--sen-clear);color:var(--sen-ink);filter:none;opacity:1;text-shadow:none;box-shadow:none}
#chat .mes_reasoning {font-family:var(--sen-font);line-height:1.8}
#chat :is(.mes_button,.menu_button,.edit_textarea,.reasoning_edit_textarea,a):focus-visible,
#top-settings-holder .drawer-icon:focus-visible,
#send_form :is(textarea,button,[tabindex]):focus-visible {outline:2px solid var(--sen-focus);outline-offset:2px}
#send_form:has(#send_textarea:focus-visible) {outline:2px solid var(--sen-focus);border-color:var(--sen-focus)}
@media (max-width:700px) {
 #top-settings-holder .drawer-icon {font-size:20px;min-inline-size:26px;padding:3px}
 #send_form {padding:3px}
 #send_form #leftSendForm > div,#send_form #rightSendForm > div:not(.mes_stop) {width:32px;height:38px}
 #send_textarea {padding-inline:8px}
}



